function locate(doc, tokens, notFound, fail) {
  const parent = follow(doc, tokens.slice(0, -1), notFound, fail);
  const key = tokens[tokens.length - 1];
  const reason = missReason(parent, key, notFound);
  if (reason !== null) fail(reason);
  return { parent, key };
}

