27	// Collects chunks from an async iterable, stopping once the byte limit is passed.
28	async function collect(chunks, name) {
29	  const parts = [];
30	  let total = 0;
31	  for await (const chunk of chunks) {
32	    total += chunk.length;
33	    if (total > MAX_BYTES) throw readError(name, 'too large');
34	    parts.push(chunk);
35	  }
36	  return Buffer.concat(parts, total);
